import {BANK,LESSONS} from './handwriting-bank.js';
import {WritingCanvas} from './handwriting-canvas.js';
import {load,save,record,exportData,importData} from './handwriting-storage.js';
import {points} from './handwriting-grading.js';
import {selectRound} from './handwriting-selection.js';
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
const $=id=>document.getElementById(id);let data=load(),mode='normal',set=[],at=0,score=0,streak=0,hinted=false,submitted=false,timerId=null,timeLeft=90;
const canvas=new WritingCanvas($('canvas'),()=>{$('submit').disabled=!canvas.hasInk||submitted});
$('canvas').addEventListener('pointerdown',e=>canvas.start(e));$('canvas').addEventListener('pointermove',e=>canvas.move(e));for(const event of ['pointerup','pointercancel'])$('canvas').addEventListener(event,e=>canvas.end(e));
LESSONS.forEach(([name],i)=>{const o=document.createElement('option');o.value=i+1;o.textContent=name;$('lesson').append(o)});
function view(id){for(const x of ['menu','play','done'])$(x).hidden=x!==id;window.scrollTo(0,0);if(id==='play')requestAnimationFrame(()=>canvas.resize())}
function updateStats(){const items=Object.values(data.items),done=items.filter(x=>x.correct>0&&!x.review).length,review=items.filter(x=>x.review).length;const today=new Date().toLocaleDateString('en-CA');const daily=data.history.filter(h=>new Date(h.date).toLocaleDateString('en-CA')===today).length;$('stats').textContent=`已練習 ${items.length}/${BANK.length} 字 · 熟練 ${done} 字 · 待複習 ${review} 字 · 今天 ${daily} 次作答`;$('total').textContent=`自行核對積分 ${data.history.reduce((n,h)=>n+(h.points||0),0)}`;$('lesson-stats').textContent=LESSONS.map((lesson,i)=>{const qs=BANK.filter(q=>q.lessonIndex===i+1);const mastered=qs.filter(q=>data.items[q.id]?.correct>0&&!data.items[q.id]?.review).length;return `${lesson[0]}：${mastered}/${qs.length}${mastered===qs.length?' ★':''}`}).join('　｜　')+(done===BANK.length?'　🏆 十二課全部完成！':'')}
updateStats();
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(b.dataset.mode));
function start(chosen){mode=chosen;const lv=$('lesson').value;let pool=BANK.filter(q=>lv==='all'||(lv==='final'?q.lessonIndex>=7:q.lessonIndex===Number(lv)));if(mode==='review')pool=pool.filter(q=>data.items[q.id]?.review).sort((a,b)=>(data.items[b.id].wrong*3+data.items[b.id].unsure)-(data.items[a.id].wrong*3+data.items[a.id].unsure));const count=$('count').value==='all'?pool.length:Number($('count').value);if(!pool.length){$('notice').textContent=mode==='review'?'目前沒有待複習的字。':'目前沒有可用題目。';return}if(count>pool.length&&$('count').value!=='all'&&mode!=='review'){$('notice').textContent=`目前只有 ${pool.length} 題，請選較少題數或「全部題目」。`;return}$('notice').textContent='';if(mode==='review')set=pool.slice(0,count);else{data.rounds??={};set=selectRound(pool,count,`${mode}:${$('lesson').value}`,data.rounds);save(data)}if(mode==='review'&&$('triple').checked)set=set.flatMap(q=>[q,q,q]);at=0;score=0;streak=0;view('play');render()}
function render(){clearInterval(timerId);const q=set[at];hinted=false;submitted=false;canvas.clear();$('progress').textContent=`第 ${at+1} / ${set.length} 題`;$('fill').style.width=`${at/set.length*100}%`;$('score').textContent=`本回合自行核對 ${score} 分`;$('source').textContent=q.page?`${q.lesson} · 課本第 ${q.page} 頁生字欄`:`${q.lesson} · 期末生字表`;$('prompt').textContent=mode==='advanced'?`寫出「${q.zhuyin}」的國字`:`注音：${q.zhuyin}`;$('word').textContent=mode==='advanced'?'':`語詞：${q.word.replace(q.character,'□')}`;$('sentence').textContent=mode==='basic'?'依課文情境練習：'+q.sentence:`依課文情境練習：${q.sentence.replaceAll(q.character,'□')}`;$('trace').textContent=mode==='basic'?q.character:'';$('grade').hidden=true;$('answer').textContent='';$('task-notice').textContent='';$('hint').hidden=mode==='basic';$('hint').disabled=false;$('submit').disabled=true;$('submit').hidden=mode==='basic';if(mode==='basic'){$('task-notice').textContent='基礎描紅不計分。可清空、復原，完成後按「下一題」。';$('submit').hidden=false;$('submit').textContent='下一題';$('submit').disabled=false}else $('submit').textContent='交卷批改';if(mode==='advanced'&&$('timer').checked){timeLeft=90;$('clock').textContent=`剩餘 ${timeLeft} 秒`;timerId=setInterval(()=>{timeLeft--;$('clock').textContent=`剩餘 ${timeLeft} 秒`;if(timeLeft<=0){clearInterval(timerId);$('task-notice').textContent='時間到，仍可完成這題並自行核對。'}},1000)}else $('clock').textContent=''}
$('undo').onclick=()=>canvas.undo();$('clear').onclick=()=>canvas.clear();$('hint').onclick=()=>{const q=set[at];hinted=true;$('task-notice').textContent=`提示：這是${q.lesson}${q.page?`第 ${q.page} 頁生字欄`:'生字表'}的字；可回想課文情境。這題會記錄使用提示。`;$('hint').disabled=true};
$('submit').onclick=()=>{if(mode==='basic'){next();return}if(!canvas.hasInk){$('task-notice').textContent='請先在田字格寫字。';return}clearInterval(timerId);submitted=true;$('submit').disabled=true;$('hint').disabled=true;$('answer').textContent=set[at].character;$('grade').hidden=false};
document.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>{if(!submitted)return;const result=b.dataset.result,q=set[at];streak=result==='correct'&&!hinted?streak+1:0;const earned=points(result,hinted,mode,streak);score+=earned;record(data,q,result,hinted,mode);data.history[data.history.length-1].points=earned;localStorage.setItem('grade6-chinese-handwriting-v1',JSON.stringify(data));next()});
function next(){at++;if(at<set.length){render();return}clearInterval(timerId);view('done');const good=data.history.slice(-set.length).filter(h=>h.result==='correct'&&h.mode===mode).length;$('done-title').textContent='這回合完成！';$('done-detail').textContent=mode==='basic'?`完成 ${set.length} 題描紅練習。`:`完成 ${set.length} 題，自己核對寫對 ${good} 題，得到 ${score} 分。錯字與不確定的字已放入再挑戰。`;updateStats()}
$('again').onclick=()=>view('menu');$('export').onclick=()=>exportData(data);$('import').onchange=async e=>{try{data=await importData(e.target.files[0]);updateStats();$('notice').textContent='紀錄匯入成功。'}catch{$('notice').textContent='匯入失敗，請選擇本遊戲匯出的 JSON 紀錄。'}e.target.value=''};
